def max_drawdown(returns):
    if not returns:
        return 0.0

    wealth = 1.0
    peak = 1.0
    max_dd = 0.0

    for r in returns:
        wealth *= (1.0 + r)
        if wealth > peak:
            peak = wealth
        drawdown = (wealth - peak) / peak
        if drawdown < max_dd:
            max_dd = drawdown

    return max_dd
