def max_drawdown(returns):
    wealth_index = [1.0]
    for r in returns:
        wealth_index.append(wealth_index[-1] * (1 + r))
    wealth_index = wealth_index[1:]
    peak = 1.0
    max_drawdown = 0.0
    for value in wealth_index:
        if value > peak:
            peak = value
        drawdown = (value - peak) / peak
        if drawdown < max_drawdown:
            max_drawdown = drawdown
    return max_drawdown
